steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issue(identifier: \"MOB-3\") {
        id
        identifier
        title
        labelIds
        labels {
          id
          name
        }
      }
      issueLabels {
        nodes {
          id
          name
          group
        }
      }
    }"
  }'
